const productosPedido =
$('Parsear Productos Texto').first().json.productos;

let total = 0;
let resumen = [];
let agotados = [];

for (const fila of $input.all()) {

  const nombre = fila.json.nombre;
  const precio = Number(fila.json.precio);
  const stock = Number(fila.json.stock);

  if (productosPedido.includes(nombre)) {

    if (stock <= 0) {

      agotados.push(nombre);

      continue;

    }

    total += precio;

    resumen.push(
      `${nombre} - $${precio}`
    );

  }

}

return [{
json:{

agotados,

carrito_temporal:
resumen.join('\n'),

precio_temporal:
total,

nombre_temporal:"",

pantalla_actual:
"esperando_confirmacion",

telegram_id:
$('Telegram Trigger')
.first()
.json.message.chat.id,

ultimo_cambio:
new Date().toLocaleString('es-CO')

}
}];

