return [{
json:{
telegram_id: $('Leer Sesión Activa').first().json.telegram_id,

mensaje:
`🔔 NUEVO PEDIDO

🆔 Pedido:
${$('Guardar Pedido').first().json.id_pedido}

🛒 Productos:
${$('Leer Sesión Activa').first().json.carrito_temporal}

💰 Total:
$${$('Leer Sesión Activa').first().json.precio_temporal}`
}
}];

const pedidos = $input.all();

let mensaje = "📋 PEDIDOS PENDIENTES\n\n";

for (const pedido of pedidos) {

  const estado = pedido.json.estado;

  if (
    estado !== "Entregado" &&
    estado !== "entregado"
  ) {

    mensaje +=
`🆔 ${$input.first().json.id_pedido}
📦 Estado: ${$input.first().json.estado}
🛒 ${$input.first().json.detalles_pedido}
💰 Total: $${$input.first().json.total_pago}

`;

  }

}

if (mensaje === "📋 PEDIDOS PENDIENTES\n\n") {

  mensaje += "No hay pedidos pendientes.";

}

return [{
  json: {
    mensaje
  }
}];

const pedidos = $input.all();

let totalVentas = 0;
let cantidadPedidos = 0;

const productos = {};
const horas = {};

for (const pedido of pedidos) {

  cantidadPedidos++;

  totalVentas += Number(
    pedido.json.total_pago || 0
  );

  // Productos vendidos

  const detalle =
    pedido.json.detalles_pedido || "";

  const listaProductos =
    detalle.split(",");

  for (let producto of listaProductos) {

    producto = producto.trim();

    if (!producto) continue;

    productos[producto] =
      (productos[producto] || 0) + 1;

  }

  // Hora pico

  const hora =
    pedido.json.hora;

  if (hora) {

    horas[hora] =
      (horas[hora] || 0) + 1;

  }

}

// Producto estrella

let productoEstrella =
  "Sin datos";

let maxProductos = 0;

for (const producto in productos) {

  if (
    productos[producto] >
    maxProductos
  ) {

    maxProductos =
      productos[producto];

    productoEstrella =
      producto;

  }

}

// Hora pico

let horaPico =
  "Sin datos";

let maxHoras = 0;

for (const hora in horas) {

  if (
    horas[hora] >
    maxHoras
  ) {

    maxHoras =
      horas[hora];

    horaPico =
      hora;

  }

}

return [{
  json: {

    mensaje:

`📊 REPORTE FINANCIERO

💰 Total vendido:
$${totalVentas}

📦 Pedidos:
${cantidadPedidos}

🏆 Producto estrella:
${productoEstrella}

⏰ Hora pico:
${horaPico}`

  }
}];

const detalle =
$('Guardar Pedido').first().json.detalles_pedido;

const productosPedido =
detalle
.split('\n')
.map(x => x.split(' - ')[0].trim());

let resultado = [];

for (const item of $input.all()) {

  const producto =
  item.json.nombre;

  let stock =
  Number(item.json.stock);

  if (
    productosPedido.includes(producto)
  ) {

    stock--;

    resultado.push({
      json:{
        id_producto:
        item.json.id_producto,

        nombre:
        producto,

        stock:
        stock
      }
    });

  }

}

return resultado;

const productosPedido =
$('Parsear Productos Texto').first().json.productos;

const productosMenu =
$input.all().map(
item => item.json.nombre
);

const noEncontrados =
productosPedido.filter(
producto =>
!productosMenu.includes(producto)
);

return [{
json:{
productosPedido,
productosMenu,
noEncontrados,
esValido:
noEncontrados.length === 0
}
}];

